module tb;

  // ------------------------------------------------------------
  // Parameters
  // ------------------------------------------------------------
  localparam int CLK_HALF = 4;                 // 8‑ns period → 125 MHz
  localparam logic [15:0] PRESCALE_VAL = 16'd5;

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  logic clk = 0;
  always #CLK_HALF clk = ~clk;

  logic rst = 1'b1;
  initial begin
    #20 rst = 1'b0;
    #20 rst = 1'b1;
    #20 rst = 1'b0;
  end

  // ------------------------------------------------------------
  // DUT‑visible signals (re‑exported for coverage check)
  // ------------------------------------------------------------
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready;
  logic [15:0] prescale = PRESCALE_VAL;
  logic       frame_error;
  logic       rxd = 1'b1;                     // UART line (output of TB)

  // AXI‑stream ready is always high
  assign m_axis_tready = 1'b1;

  // ------------------------------------------------------------
  // DUT instantiation
  // ------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk         (clk),
    .rst         (rst),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd         (rxd),
    .busy        (),          // unused
    .overrun_error(),        // unused
    .frame_error (frame_error),
    .prescale    (prescale)
  );

  // ------------------------------------------------------------
  // Task: send one byte and force a framing error (stop bit low)
  // ------------------------------------------------------------
  task automatic send_byte_error(input byte unsigned data);
    int bit_clks = int'(prescale) * 8;

    // start bit – low for one bit period
    rxd = 1'b0;
    #bit_clks;

    // 8 data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      rxd = data[i];
      #bit_clks;
    end

    // stop bit – drive low to generate a frame error
    rxd = 1'b0;
    #bit_clks;
  endtask

  // ------------------------------------------------------------
  // Coverage check – finish when R29 condition is satisfied
  // ------------------------------------------------------------
  always @(posedge clk) begin
    if (!rst) begin
      // $past() references the value from the previous rising edge
      if (!$past(rst) &&                     // rst was low in previous cycle
          $past(frame_error) &&               // frame_error was high last cycle
          $past(m_axis_tvalid) &&             // m_axis_tvalid was high last cycle
          $past(m_axis_tready) &&             // m_axis_tready was high last cycle
          ($past(m_axis_tdata) == 8'h3C) &&   // data was 0x3C last cycle
          !m_axis_tvalid &&                   // now tvalid is low
          (m_axis_tdata == 8'h3C)) begin      // and data still 0x3C
        $finish;   // successful completion
      end
    end
  end

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Wait until reset is released
    @(negedge rst);
    #1;

    // Trigger the error‑inducing transaction with data 0x3C
    send_byte_error(8'h3C);

    // Safety timeout – should never be reached if coverage is hit
    #5000000;
    $display("Timeout – coverage point not observed");
    $finish;
  end

  // ------------------------------------------------------------
  // Initialise UART line (idle state)
  // ------------------------------------------------------------
  initial rxd = 1'b1;

endmodule

module tb;

  // -------------------------------------------------
  // Parameters
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8;          // 125 MHz
  localparam int BIT_CLOCKS = 40;         // prescale = 5 → 5*8 = 40

  // -------------------------------------------------
  // Clock generation
  // -------------------------------------------------
  reg clk = 0;
  initial begin
    forever #(CLK_PERIOD/2) clk = ~clk;
  end

  // -------------------------------------------------
  // Reset (active‑high)
  // -------------------------------------------------
  reg rst = 1;

  // -------------------------------------------------
  // Prescale value (must be non‑zero when required)
  // -------------------------------------------------
  wire [15:0] prescale_val = 16'd5;       // constant non‑zero

  // -------------------------------------------------
  // UART_RX interface signals
  // -------------------------------------------------
  logic rxd;
  logic [7:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready;
  logic busy;
  logic overrun_error;
  logic frame_error;

  // -------------------------------------------------
  // AXI‑Stream tready is permanently high (receiver always ready)
  // -------------------------------------------------
  initial begin
    m_axis_tready = 1'b1;
  end

  // -------------------------------------------------
  // Connect constant prescale to the DUT
  // -------------------------------------------------
  assign prescale_val = 16'd5;

  // -------------------------------------------------
  // Instantiate the RX module (coverage is bound to this instance)
  // -------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale_val)
  );

  // -------------------------------------------------
  // Helper task: wait for N negative‑edge clock cycles
  // -------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  // -------------------------------------------------
  // Task: transmit a complete UART frame on rxd
  //   stop_low = 1'b1 forces a low stop bit → frame_error is generated
  // -------------------------------------------------
  task automatic send_frame(input byte unsigned data, input logic stop_low);
    begin
      // START bit
      rxd = 1'b0;
      wait_clks(BIT_CLOCKS);
      // Data bits, LSB first
      for (int i = 0; i < 8; i++) begin
        rxd = data[i];
        wait_clks(BIT_CLOCKS);
      end
      // STOP bit
      if (stop_low) rxd = 1'b0; else rxd = 1'b1;
      wait_clks(BIT_CLOCKS);
      // Return to idle
      rxd = 1'b1;
    end
  endtask

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
  initial begin
    // Stabilise clock
    # (CLK_PERIOD*2);
    // De‑assert reset
    rst = 1;
    wait_clks(2);
    rst = 0;
    wait_clks(2);
    // Ensure we are past reset
    repeat (5) @(negedge clk);

    // Idle state on rxd
    rxd = 1'b1;

    // -------------------------------------------------
    // 1) Generate a frame error (stop bit low)
    // -------------------------------------------------
    send_frame(8'h00, 1'b1);
    // Allow frame_error to be set and stabilised
    repeat (12) @(negedge clk);

    // -------------------------------------------------
    // 2) Send the word 0x3C with a proper (high) stop bit.
    //    This frame is accepted while the previous frame_error
    //    is still high, satisfying the $past(frame_error) condition.
    // -------------------------------------------------
    send_frame(8'h3C, 1'b0);
    // Wait long enough for the handshake to complete,
    // tvalid to drop, and for the cover property to be evaluated.
    repeat (30) @(negedge clk);

    // If we reach here the target coverage point has been hit.
    $display("TESTBENCH COMPLETED");
    $finish;
  end

endmodule

module tb;
  // -------------------------------------------------
  //  Top‑level testbench for the AXI‑Stream UART
  // -------------------------------------------------
  //  All signals are connected only through the DUT ports.
  //  The design is exercised until the coverage point
  //  R29_accept_during_frame_error is hit, then $finish()
  //  is called.
  // -------------------------------------------------

  // -------------------------------------------------
  //  Clock and reset
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8;                 // 125 MHz
  logic clk        = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------
  //  DUT ports (default parameters)
  // -------------------------------------------------
  logic        rst;
  logic [15:0] prescale;
  logic        rxd;
  logic        s_axis_tvalid;
  logic [7:0]  s_axis_tdata;

  //  AXI‑Stream output of the RX side
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;   // driven by the testbench

  //  Additional status ports (unused)
  logic        tx_busy;
  logic        rx_busy;
  logic        rx_overrun_error;
  logic        rx_frame_error;

  // -------------------------------------------------
  //  Connect the DUT
  // -------------------------------------------------
  logic unused_s_axis_tready;   // DUT output – left un‑driven
  assign unused_s_axis_tready = 1'b0;

  uart #(.DATA_WIDTH(8)) dut (
    .clk                (clk),
    .rst                (rst),
    .s_axis_tdata       (s_axis_tdata),
    .s_axis_tvalid      (s_axis_tvalid),
    .s_axis_tready      (unused_s_axis_tready), // output, not driven
    .m_axis_tdata       (m_axis_tdata),
    .m_axis_tvalid      (m_axis_tvalid),
    .m_axis_tready      (m_axis_tready),        // input – driven by TB
    .rxd                (rxd),
    .txd                (),
    .tx_busy            (),
    .rx_busy            (),
    .rx_overrun_error   (),
    .rx_frame_error     (rx_frame_error),
    .prescale           (prescale)
  );

  // -------------------------------------------------
  //  Simple clock generation
  // -------------------------------------------------
  initial clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------
  //  Reset sequence
  // -------------------------------------------------
  initial begin
    rst          = 1'b1;
    prescale     = 16'd5;
    rxd          = 1'b1;
    s_axis_tdata   = 8'h00;
    s_axis_tvalid  = 1'b0;
    m_axis_tready  = 1'b0;
    # (CLK_PERIOD*20);
    rst          = 1'b0;
  end

  // -------------------------------------------------
  //  Helpers
  // -------------------------------------------------
  task automatic wait_cycles(input int n);
    repeat (n) @(posedge clk);
  endtask

  // Drive rxd for a given number of clock cycles
  task automatic drive_rxd(input logic level, input int cycles);
    rxd <= level;
    wait_cycles(cycles);
  endtask

  // Send one UART byte (LSB‑first) – optional stop bit
  task automatic uart_send_byte(input logic [7:0] data, input logic stop_high);
    // start bit
    drive_rxd(1'b0, 40);
    // data bits
    for (int i = 0; i < 8; i++) begin
      drive_rxd(data[i], 40);
    end
    // stop bit
    drive_rxd(stop_high ? 1'b1 : 1'b0, 40);
  endtask

  // -------------------------------------------------
  //  Coverage‑point monitor
  // -------------------------------------------------
  always @(posedge clk) begin
    if (!rst &&
        !$past(rst) &&
        $past(rx_frame_error) &&
        $past(m_axis_tvalid) &&
        $past(m_axis_tready) &&
        ($past(m_axis_tdata) == 8'h3C) &&
        !m_axis_tvalid &&
        (m_axis_tdata == 8'h3C)) begin
      $finish;
    end
  end

  // -------------------------------------------------
  //  Main stimulus
  // -------------------------------------------------
  initial begin
    // -----------------------------------------------------------------
    //  1) Wait for reset de‑assertion
    // -----------------------------------------------------------------
    @(negedge rst);
    #100;

    // -----------------------------------------------------------------
    //  2) Force a frame‑error by sending a malformed frame
    //     (start‑bit, 8 data bits, stop‑bit low).
    // -----------------------------------------------------------------
    uart_send_byte(8'h00, 1'b0);   // stop bit low → frame_error asserted

    // Allow a few cycles for the error to be latched
    repeat (5) @(posedge clk);

    // -----------------------------------------------------------------
    //  3) Now send the word 0x3C with a proper stop bit.
    //     While the word is being received we keep m_axis_tready high
    //     so the Rx accepts it immediately.
    // -----------------------------------------------------------------
    m_axis_tready = 1'b1;                 // always ready
    uart_send_byte(8'h3C, 1'b1);           // data = 0x3C, stop‑bit high

    // Wait until the coverage condition can be evaluated
    repeat (30) @(posedge clk);

    // -----------------------------------------------------------------
    //  4) End of simulation – $finish is called automatically
    // -----------------------------------------------------------------
    $finish;
  end

endmodule

`timescale 1ns / 1ps

module tb;
  localparam int CLK_PERIOD = 10;
  localparam logic [15:0] PRESCALE = 16'd1;

  logic clk = 0;
  logic rst = 0;
  logic [7:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready = 0;
  logic rxd = 1;
  logic [15:0] prescale = PRESCALE;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;
  logic [7:0] s_axis_tdata = 0;
  logic s_axis_tvalid = 0;
  logic s_axis_tready;
  logic txd;
  logic tx_busy;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart #(.DATA_WIDTH(8)) dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1;
    wait_clks(4);
    rst = 0;
    wait_clks(2);
  endtask

  initial begin
    m_axis_tready = 0;
    rxd = 1;
    s_axis_tdata = 0;
    s_axis_tvalid = 0;
    prescale = PRESCALE;

    do_reset();

    // ---- Frame 1: data 0x3C, good stop bit, sink stalled (tready=0) ----
    // After this frame m_axis_tvalid=1, m_axis_tdata=0x3C, held unread.
    rxd = 0;
    wait_clks(int'(prescale) * 8);
    for (int i = 0; i < 8; i++) begin
      rxd = (8'h3C >> i) & 1'b1;
      wait_clks(int'(prescale) * 8);
    end
    rxd = 1;
    wait_clks(int'(prescale) * 8);

    // Wait until the word is presented on the AXI output
    do @(negedge clk); while (!m_axis_tvalid);
    if (m_axis_tdata !== 8'h3C) begin
      $display("FAIL: unexpected tdata 0x%02h", m_axis_tdata);
      $finish;
    end

    // ---- Frame 2: all-zero data, bad stop bit (0) -> frame_error ----
    // Keep m_axis_tready low through the start + 8 data bits and 7 of the
    // 8 stop-bit clocks, then release it on the final stop-bit clock so
    // that the 0x3C handshake (tvalid&tready) lands on the same posedge
    // as the frame-error strobe.  On the next posedge tvalid has dropped
    // while tdata still holds 0x3C, satisfying R29.
    rxd = 0;
    wait_clks(int'(prescale) * 8);
    for (int i = 0; i < 8; i++) begin
      rxd = 0;
      wait_clks(int'(prescale) * 8);
    end
    rxd = 0;  // bad stop bit
    wait_clks(int'(prescale) * 8 - 1);
    m_axis_tready = 1;
    wait_clks(4);

    $finish;
  end

  initial begin
    #10ms;
    $finish;
  end

endmodule
